INSERT INTO pipeline_jobs (municipality_id, job_type, args, priority, requested_by)
SELECT municipality_id, job_type, args, priority, requested_by
FROM jobs
WHERE NOT EXISTS (
  SELECT 1 FROM pipeline_jobs existing
  WHERE existing.municipality_id = jobs.municipality_id
    AND existing.status IN ('queued', 'running')
    AND existing.args->>'archive_path' = jobs.args->>'archive_path'
);
